import{z as s,x as o,o as i,c as p,q as l,j as t,D as e,d as E,s as r,S as A,b as n}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"驻波与 BARC","description":"","frontmatter":{"title":"驻波与 BARC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/standing-wave-barc.md","filePath":"litho/standing-wave-barc.md","lastUpdated":1791413859000}'),d={name:"litho/standing-wave-barc.md"};function m(C,a,h,R,c,D){const B=o("Mermaid");return i(),p("div",null,[a[2]||(a[2]=l('<h1 id="驻波与-barc" tabindex="-1">驻波与 BARC <a class="header-anchor" href="#驻波与-barc" aria-label="Permalink to &quot;驻波与 BARC&quot;">​</a></h1><div class="epigraph"><p>衬底一反射，胶里就出现沿厚度的干涉条纹；溶解速率跟着 $I(z)$ 振荡，侧壁起波。BARC 要关掉的是这场反射，不是另做一层装饰膜。</p><footer>—— 据 Mack 对驻波与 swing curve 的讨论，以及 Levinson 对底层抗反的表述整理</footer></div><p><a href="/litho/dissolution-mack">上一课</a>把浮雕写成 \\(R(m)\\) 的积分，并默认 \\(I(z)\\) 是「给定的」。缺口是：衬底反射让入射与反射在胶里干涉，\\(I(z)\\) 以 \\(\\lambda/(2n)\\) 为周期振荡，\\(m(z)\\) 跟着振荡。本课钉驻波与底层抗反射（BARC）。剖面角如何进刻蚀，留给<a href="/litho/sidewall-angle">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的 \\(R(m)\\) 在 \\(m\\) 沿 \\(z\\) 均匀时给出光滑侧壁。晶圆上很少均匀：胶–衬底界面反射把第二列波送回来，与入射叠加，形成驻波。亮节产酸（或 DNQ 转化）多，暗节少，显影后侧壁出现与周期对应的波纹。CD 对胶厚也极敏感——这就是 swing curve：厚度变四分之一光学波长量级，CD 可以走出窗。</p><p>缺口不是再拟合一次 \\(n\\) 和 \\(m_\\mathrm{th}\\)，而是把光学薄膜栈接进 \\(I(z)\\)。只加剂量，平均 \\(m\\) 上移，波纹还在。只拧 PEB，酸扩散可以糊掉一部分 \\(z\\) 向条纹，却在付横向模糊的账。</p><p><span class="marginnote">驻波的直觉类比：两堵墙之间的教室里拍手，前进的声波和反射的声波叠加，有的位置总是响（波腹）、有的位置总是静（波节）。光在胶–衬底两界面之间来回反射，就沿胶厚方向刻出一排固定的亮暗楼层，每层楼显影速率不同。</span></p><h3 id="swing-不是剂量环能锁住的" tabindex="-1">Swing 不是剂量环能锁住的 <a class="header-anchor" href="#swing-不是剂量环能锁住的" aria-label="Permalink to &quot;Swing 不是剂量环能锁住的&quot;">​</a></h3><p>剂量闭环锁的是面能量密度的积分，不锁胶厚。涂覆均匀性、台阶上的局部厚度，走的是 swing 的横轴。BARC 的第一任务是把衬底反射压下去，从而压驻波对比与 swing 振幅。</p><p><span class="marginnote">周期是胶内 \\(\\lambda/(2n)\\)，不是真空 \\(\\lambda/2\\)。换波长、换胶折射率，条纹间距变。浸没改的是镜头侧介质，驻波仍在胶里算。不要把 NA 焦深与驻波节点当成同一个轴向问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>光学：用薄膜栈（空气/水–胶–BARC–衬底）算 \\(I(z)\\)。BARC 是高吸收或干涉相消的底层：有机 BARC 靠 \\(k\\) 吃反射；无机（如 SiON、SiARC）靠折射率与厚度做减反，并常兼硬掩模。厚度选在反射极小附近，且要对准这一层的 \\(\\lambda\\) 与入射角（高 NA 还要小心角分布）。减反极小通常有多个厚度解，要同时看刻蚀穿通与涂覆窗口，不能只盯光学反射的第一个零点。</p><p>上层抗反（TARC）减的是胶顶反射，主要改 swing 的另一头与斑点，不替代 BARC。CAR 的上层涂层还管出气与胺，功能重叠但机制不同。本课对象是底部反射 → 驻波。换金属衬底而不换 BARC，是驻波事故的常见写法。</p><h3 id="与溶解模型的接口" tabindex="-1">与溶解模型的接口 <a class="header-anchor" href="#与溶解模型的接口" aria-label="Permalink to &quot;与溶解模型的接口&quot;">​</a></h3><p>把 \\(I(z)\\) 送进产酸或 Dill 曝光，得到 \\(m(x,z)\\)，再进 Mack / Notch 的 \\(R(m)\\)。OPC 紧凑模型若假设单一平面强度，等于忽略本课；校准片必须在真实栈上做。换衬底（金属、多晶、介质）等于换反射，BARC 要重选。</p>',15)),(i(),t(A,null,{default:e(()=>[r(B,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E8%A1%AC%E5%BA%95%E5%8F%8D%E5%B0%84%22%5D%20--%3E%20SW%5B%22%E8%83%B6%E5%86%85%E9%A9%BB%E6%B3%A2%20I(z)%22%5D%0A%20%20BARC%5B%22BARC%20%E5%87%8F%E5%8F%8D%22%5D%20--%3E%20SUB%0A%20%20SW%20--%3E%20M%5B%22m(x%2Cz)%20%E6%8C%AF%E8%8D%A1%22%5D%0A%20%20R%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9AR(m)%22%5D%20--%3E%20PROF%5B%22%E6%B3%A2%E7%BA%B9%E4%BE%A7%E5%A3%81%22%5D%0A%20%20M%20--%3E%20PROF%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[E("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"入射与反射相干叠加，波腹波节沿 \\(z\\) 交替。正胶在波节处转化不足，显影后留下凸起；波腹处过转，凹进。横向看就是侧壁波纹。酸扩散（PEB）在 \\(z\\) 向也有分量，可以部分抹平条纹，这是 CAR 相对 i 线 DNQ 的额外平滑——下一课讲侧壁角时会看到「波纹被糊掉但仍有平均锥角」。没有 BARC 时，Mack 的 \\(R(m)\\) 仍然正确，只是输入 \\(m(z)\\) 已经皱了；把波纹侧壁归因于「γ 不够」会去拧显影，而不是去选 BARC。",-1)),(i(),t(A,null,{default:e(()=>[r(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22BARC%20%E9%9D%A0%E4%BB%80%E4%B9%88%E5%8E%8B%E5%8F%8D%E5%B0%84%3F%22%5D%20--%3E%20ORG%5B%22%E6%9C%89%E6%9C%BA%20BARC%22%5D%0A%20%20Q%20--%3E%20INO%5B%22%E6%97%A0%E6%9C%BA%20SiON%20%2F%20SiARC%22%5D%0A%20%20ORG%20--%3E%20K%5B%22%E5%A4%A7%E6%B6%88%E5%85%89%E7%B3%BB%E6%95%B0%20k%20%E9%80%90%E5%B1%82%E5%90%B8%E5%85%89%22%5D%0A%20%20K%20--%3E%20HARD%5B%22%E9%80%9A%E5%B8%B8%E5%85%BC%E4%BD%9C%20hardmask%20%E5%B1%82%22%5D%0A%20%20INO%20--%3E%20INT%5B%22%E6%8A%98%E5%B0%84%E7%8E%87%E4%B8%8E%E5%8E%9A%E5%BA%A6%E5%87%91%E5%B9%B2%E6%B6%89%E7%9B%B8%E6%B6%88%22%5D%0A%20%20INT%20--%3E%20ETCH%5B%22%E5%B8%B8%E5%85%BC%E7%A1%AC%E6%8E%A9%E6%A8%A1%20%E9%80%89%E6%AF%94%E8%A6%81%E6%A0%B8%22%5D%0A%20%20K%20--%3E%20MIN%5B%22%E5%85%B1%E5%90%8C%E7%9B%AE%E6%A0%87%3A%20%E5%8F%8D%E5%B0%84%E6%9E%81%E5%B0%8F%22%5D%0A%20%20ETCH%20--%3E%20MIN%0A%20%20MIN%20--%3E%20SW%5B%22swing%20%E6%8C%AF%E5%B9%85%E4%B8%8E%E9%A9%BB%E6%B3%A2%E5%AF%B9%E6%AF%94%E4%B8%80%E8%B5%B7%E9%99%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">数字实例：驻波周期是胶内 \\(\\lambda/(2n)\\)。ArF 193 nm 胶、折射率约 1.44 时，周期约 \\(193/(2 \\times 1.44) \\approx 67\\) nm；一条 200 nm 厚的胶里要叠约三层亮暗条纹——侧壁上每 67 nm 就得换一次明暗，波纹可见程度可想而知。</span></p><p><span class="marginnote">常见误区：看到侧壁波纹先去加剂量或调显影。剂量只抬平均转化率，条纹的相对起伏一点没少；正确动作是把衬底反射压下去（选 BARC 或换栈），再谈显影参数。</span></p><p>Swing：胶厚变，入射与反射的相位差变，耦合进胶的能量变，平均 CD 随厚度振荡。BARC 把反射振幅打下来，振荡幅度下降，涂胶窗口才打得开。高 NA、大入射角使有效路径与偏振分裂，减反条件变窄，这是矢量成像课已经警告过的薄膜缺口，本课落到 BARC 工艺。</p><p><span class="marginnote">BARC 开口以后，刻蚀要先穿 BARC 再刻衬底。减反膜同时是刻蚀栈的一层，选择比与残留进 AEI。光学最优厚度若刻不穿，光学窗会输给转印。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某品牌 BARC 的 \\(n\\)、\\(k\\) 表，不把「有机一定不如无机」写成定律。EUV 反射掩模与晶圆侧底层是另一套吸收逻辑，后课 EUV 底层再声明。不要把 flare 当成驻波：flare 是长程杂散，驻波是薄膜相干。</p><p>侧壁角的平均值（锥形、倒锥）即使驻波被压平也还在，来自吸收体效应与显影。下一课接这条几何，不再重推干涉。</p><p>换衬底金属或介质而不重选 BARC，是驻波事故的常见写法。光学最优若刻不穿，转印优先。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>衬底反射在胶内产生周期 \\(\\lambda/(2n)\\) 的驻波，\\(R(m)\\) 跟着振荡。</li><li>Swing curve 是 CD 对胶厚；剂量环锁不住厚度轴。</li><li>BARC 压反射，从而压驻波与 swing；它同时是刻蚀栈。</li><li>TARC 管顶反射，不替代 BARC。</li><li>下一课在减反之后仍要面对剖面角。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；Levinson, <em>Principles of Lithography</em>。</li></ul>',10))])}const b=s(d,[["render",m]]);export{g as __pageData,b as default};
